{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Vorozole, the closest analogue with a diarylmethyl-triazole core, has excellent oral bioavailability in postmenopausal women, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Isavuconazole, which contains a cyanophenyl and triazole, has >95% oral bioavailability in humans, supporting high F for the query's cyanophenyl-triazole motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Fluconazole, a small neutral triazole antifungal, has >90% absolute oral bioavailability with no first-pass metabolism, supporting high F for a small triazole.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Voriconazole has approximately 86% oral bioavailability in healthy volunteers, supporting high F for triazole antifungals.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Ravuconazole, containing a cyanophenyl and triazole, is 50% bioavailable at a 200 mg oral solution, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Genaconazole has 100% oral bioavailability in healthy volunteers, supporting high F for triazole antifungals.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Dapivirine, a larger diarylpyrimidine with a cyanophenyl, has low oral bioavailability, but its different scaffold and larger size limit transferability; weak contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C25"],
      "claim": "Etravirine, a larger cyanophenyl-containing NNRTI, showed low bioavailability in an early PEG formulation, but this is formulation/class-specific and weakly transferable; weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small, neutral triazole with two para-cyanophenyl groups. Multiple structurally related triazole antifungals show high oral bioavailability (50-100%), and the closest analogue vorozole has excellent oral bioavailability. Low-bioavailability analogues are structurally distinct and weakly transferable. Therefore, F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Quantitative F values for the low-bioavailability analogues are not precisely reported.",
    "Metabolic fate of the two nitrile groups is unknown, though not a clear bioavailability liability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

